/** * WakeOnLan Win10 (Custom) * Device Driver for Hubitat Elevation * * Purpose: * Transmits Wake-on-LAN (WOL) UDP magic packets across local or remote IP targets * to power on networked workstations. **//** * Copyright 2026 James Shimota * * Licensed under the Apache License, Version 2.0 (the "License"); * you may not use this file except in compliance with the License. * You may obtain a copy of the License at: * *     http://www.apache.org/licenses/LICENSE-2.0 * * Unless required by applicable law or agreed to in writing, software * distributed under the License is distributed on an "AS IS" BASIS, * WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied. * See the License for the specific language governing permissions and * limitations under the License. **//** * Changelog: * v1.0.5   09/17/26    jshimota    Removed Health Check engine completely (virtual device); updated MAC Address description regarding delimiter stripping. * v1.0.4   09/17/26    jshimota    Updated driver metadata name and comments to WakeOnLan Win10 (Custom). * v1.0.3   09/17/26    jshimota    Added useSecureOn toggle preference; default UDP Port set to 9; renamed Port to UDP Port. * v1.0.2   09/10/26    jshimota    Added off() command handler with info log output to satisfy Switch capability requirement. * v1.0.1   09/10/26    jshimota    Added MAC/Port normalization & validation, fixed conditional SecureOn packet assembly, removed dead timeout code. * v1.0.0   09/10/26    jshimota    Initial release based on standardized driver template v1.0.11. **/// [KEEP-EXACT] See possible changelog.txt for past changelog history.static String version() { return '1.0.5' }def timeStamp() { return "2026/09/17 08:45 AM" }import groovy.transform.Fieldmetadata {    definition (        name: "WakeOnLan Win10 (Custom)",         namespace: "jshimota",         author: "James Shimota",         importUrl: ""    ) {        capability "Actuator"        capability "Configuration"        capability "Refresh"        capability "Momentary"        capability "Switch"        capability "PushableButton"        // Custom Commands        command "wake"        command "resetDriver"    }    preferences {        input name: "myMac", type: "text", title: "<b>MAC Address</b>", description: "MAC address of the targeted workstation (delimiters ':' and '-' will be automatically stripped)", required: true        input name: "myIP", type: "text", title: "<b>IP Address</b>", description: "Default: 255.255.255.255 (Subnet Broadcast)", defaultValue: "255.255.255.255", required: false        input name: "myPort", type: "number", title: "<b>UDP Port</b>", description: "Default: 9", defaultValue: 9, required: false        input name: "useSecureOn", type: "bool", title: "<b>Use SecureOn Password?</b>", description: "Enable or disable SecureOn password execution", defaultValue: false, required: true        input name: "mySecureOn", type: "text", title: "<b>SecureOn Password</b>", description: "Optional 12-character hex password", required: false        // Independent Logging Switches        input name: "logInfoEnable", type: "bool", title: "Logging - Enable Info Logging", description: "Enable to output normal activity to log<br>Default: <b>On</b>", defaultValue: true, required: true        input name: "logErrorEnable", type: "bool", title: "Logging - Enable Error Logging", description: "Enable to output error activity to log<br>Default: <b>On</b>", defaultValue: true, required: true        input name: "logWarnEnable", type: "bool", title: "Logging - Enable Warning Logging", description: "Enable to output warning activity to log<br>Default: <b>On</b>", defaultValue: true, required: true        input name: "logDebugEnable", type: "bool", title: "Logging - Enable Debug Logging", description: "Enable to output debugging activity to log<br>Default: <b>Off</b><br>(Is turned on for 30 minutes after Initialized or first installed)", defaultValue: false, required: true        input name: "logTraceEnable", type: "bool", title: "Logging - Enable Trace Logging", description: "Enable to output tracing activity to log<br>Default: <b>Off</b>", defaultValue: false, required: true    }}// Single-Shot Version Demarcation Trace Logging Helper Routineprivate void checkAndLogVersionDemarcation() {    String currentVer = version()    if (state.driverVersion != currentVer) {        logTrace "=================== DRIVER VERSION UPDATE: v${currentVer} (${timeStamp()}) ==================="        state.driverVersion = currentVer    }}def refresh() {    logInfo "refresh() requested"}/* =========================================================================================   COMMAND HANDLERS & HELPERS   ========================================================================================= */void on() { wake() }void off() {    logInfo "off() command received: 'Off' was triggered, but Wake-on-LAN is a wake-only action and has no turn-off functionality."}void push() { wake() }void push(buttonNumber) { wake() }private String normalizeMac(String mac) {    if (!mac) return null    String normalized = mac.replaceAll(/[^0-9A-Fa-f]/, '').toUpperCase()    return (normalized ==~ /[0-9A-F]{12}/) ? normalized : null}void wake() {    logInfo "wake() command executed"        String macHEX = normalizeMac(myMac)    if (!macHEX) {        logError "Invalid MAC Address '${myMac}'. WOL transmission aborted."        return    }    Integer port = myPort ? myPort.toInteger() : 9    if (port < 1 || port > 65535) {        logError "Invalid UDP port '${myPort}'. WOL transmission aborted."        return    }    String ip = myIP ?: "255.255.255.255"    String command = "FFFFFFFFFFFF" + (macHEX * 16)    Boolean shouldApplySecureOn = (useSecureOn != null) ? useSecureOn : false    if (shouldApplySecureOn) {        if (mySecureOn) {            String cleanSecureOn = mySecureOn.replaceAll(/[^0-9A-Fa-f]/, '').toUpperCase()            if (cleanSecureOn ==~ /[0-9A-F]{12}/) {                command += cleanSecureOn            } else {                logWarn "SecureOn password '${mySecureOn}' is invalid (must be 12 hex characters). Transmitting packet without SecureOn payload."            }        } else {            logWarn "SecureOn toggle is ON, but no password was provided. Transmitting packet without SecureOn payload."        }    }    def myHubAction = new hubitat.device.HubAction(        command,        hubitat.device.Protocol.LAN,        [            type: hubitat.device.HubAction.Type.LAN_TYPE_UDPCLIENT,            destinationAddress: "${ip}:${port}",            encoding: hubitat.device.HubAction.Encoding.HEX_STRING        ]    )    sendHubCommand(myHubAction)    logInfo "Sent WOL magic packet to MAC ${macHEX} (${ip}:${port})"}/* =========================================================================================   HUBITAT LIFECYCLE ROUTINES   ========================================================================================= */void installed() {    checkAndLogVersionDemarcation()    logInfo "Installing driver v${version()} (${timeStamp()})..."    sendEvent(name: "numberOfButtons", value: 1)    initialize(true)}void updated() {    checkAndLogVersionDemarcation()    logInfo "Preferences updated"    String cleanMac = normalizeMac(myMac)    device.updateDataValue("MAC", cleanMac ?: "")    device.updateDataValue("SecureOn", (useSecureOn && mySecureOn) ? "configured" : "none")    device.updateDataValue("IP", myIP ?: "255.255.255.255")    device.updateDataValue("Port", myPort ? "${myPort}" : "9")    device.updateDataValue("parentDriver", "WakeOnLan Win10 (Custom)")    device.updateDataValue("driverVersion", version())        sendEvent(name: "numberOfButtons", value: 1)    initialize(false)}def configure() {    checkAndLogVersionDemarcation()    logInfo "configure() requested."    sendEvent(name: "numberOfButtons", value: 1)    initialize(false)}private void initialize(Boolean isInstall = false) {    checkAndLogVersionDemarcation()    unschedule("disableDebugLogging")    if (isInstall) {        device.updateSetting("logDebugEnable", [type: "bool", value: true])        logInfo "Debug logging enabled for 30 minutes."        runIn(1800, "disableDebugLogging")    } else if (getSettingBool("logDebugEnable", false)) {        logInfo "Debug logging enabled. Will automatically turn off in 30 minutes."        runIn(1800, "disableDebugLogging", [overwrite: false])    } else {        unschedule("disableDebugLogging")    }}/* =========================================================================================   MASTER UTILITY ROUTINES & LOGGING ENGINE   ========================================================================================= */void disableDebugLogging() {    if (getSettingBool("logDebugEnable", false)) {        logWarn "30 minutes have elapsed. Automatically disabling debug logging."        device.updateSetting("logDebugEnable", [type: "bool", value: false])    }}void resetDriver() {    logInfo "Starting full driver reset..."    clearAllSchedules()    clearAllAttributes()    clearAllDriverStates()    initialize(false)    logInfo "Driver reset process completed and re-initialized."}void clearAllDriverStates() {    logInfo "Clearing all driver states..."    state.clear()    logInfo "All states have been cleared."}void clearAllAttributes() {    logInfo "Clearing driver attributes..."    logInfo "Attributes cleared."}void clearAllSchedules() {    logInfo "Clearing all scheduled jobs..."    unschedule()    logInfo "All scheduled jobs have been successfully cleared."}private void logMessage(String level, String msg) {    String lowerLevel = level?.toLowerCase() ?: "info"    String devName = device.displayName ?: "Device Driver"        String settingKey = "log${lowerLevel.capitalize()}Enable"    Boolean defaultEnabled = (lowerLevel in ["info", "warn", "error"])    if (getSettingBool(settingKey, defaultEnabled)) {        log."${lowerLevel}" "${devName}: ${msg}"    }}private void logInfo(String msg)  { logMessage("info", msg) }private void logDebug(String msg) { logMessage("debug", msg) }private void logTrace(String msg) { logMessage("trace", msg) }private void logWarn(String msg)  { logMessage("warn", msg) }private void logError(String msg) { logMessage("error", msg) }private Boolean getSettingBool(String key, Boolean defaultVal = false) {    return settings[key] != null ? settings[key] as Boolean : defaultVal}